static QString withoutProp(QString text){text.remove(QRegularExpression("^[ \\t]*(?:GMAT[ \\t]+)?Prop\\.[A-Za-z0-9_]+[ \\t]*=[^;]*;[ \\t]*(?:\\n|$)",QRegularExpression::MultilineOption));return text;}
static bool near(double a,double b){return std::isfinite(a)&&std::abs(a-b)<=std::max(std::abs(b)*1e-13,1e-25);}
static QJsonObject fields(Propagator &p,const QJsonObject &settings){
 QJsonObject result;
 for(auto it=settings.begin();it!=settings.end();++it){const auto name=it.key().toStdString();if(it.key()=="StopIfAccuracyIsViolated")result[it.key()]=p.GetBooleanParameter(name);else if(it.key()=="MaxStepAttempts")result[it.key()]=p.GetIntegerParameter(name);else result[it.key()]=p.GetRealParameter(name);}
 return result;
}
